contract InvMutTest {
    C c;
    bool __obsd;
    uint __snap;
    constructor(C _c) {
        c = _c;
    }
    function run(uint amount) public payable {
        require(amount == 10);
        require(address(this).balance >= amount);
        c.play{value: amount}();
        assert(!__obsd || __snap == 0);
    }
    receive() external payable {
        if (!__obsd) {
            __obsd = true;
            __snap = c.pot();
        }
    }
}

