pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    uint totalReceived;

    function setUp() public {
        c = new C();
        totalReceived = 0;
    }

    function testFuzz_property(uint8 numPlays, uint64 seed) public {
        numPlays = uint8(bound(numPlays, 1, 100));
        vm.assume(seed >= 0); // seed unused, but keeps fuzzer active
        for (uint8 i = 0; i < numPlays; i++) {
            address player = address(uint160(uint(keccak256(abi.encodePacked("player", i)))));
            vm.deal(player, 10 ether);
            vm.prank(player);
            c.play{value: 10}();
            totalReceived += 10;
        }
        assertEq(
            c.pot() + address(c.bank()).balance - address(c.bank()).balance,
            totalReceived - (address(c.bank()).balance - address(c.bank()).balance) // rebalance
        );
        // Correct invariant: pot + (bank_balance - initial_bank_balance) == totalReceived
        uint initialBankBalance = address(c.bank()).balance - address(c.bank()).balance; // always 0
        assertEq(c.pot() + address(c.bank()).balance, totalReceived);
    }
}

